  const CHEST_MODEL_MAP = Object.fromEntries(((CHEST_DATA && CHEST_DATA.diminishingModels) || []).map(m => [m.id, m]));

  function syncChestModelControls() {
    const model = state.chestModelFilter || "all";
    document.querySelectorAll("#chest-model-filters [data-chest-model]").forEach(btn => {
      btn.classList.toggle("active", btn.dataset.chestModel === model);
    });
    document.querySelectorAll("#chest-models-grid [data-chest-model]").forEach(card => {
      card.classList.toggle("active", card.dataset.chestModel === model);
    });
  }

